package com.capemenuorganizer;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;

/** Editor choices only. Execution always resolves a current native menu action. */
final class CapeActionCatalog
{
	private CapeActionCatalog()
	{
	}

	static Map<String, String> utilityActions()
	{
		Map<String, String> actions = new TreeMap<>();
		actions.put("spellbook", "Spellbook");
		actions.put("features", "Features");
		for (String name : List.of("Standard", "Ancient", "Lunar", "Arceuus", "Check"))
		{
			actions.put("spellbook/" + CapeMenuTransformer.key(name), "Spellbook / " + name);
		}
		for (String name : List.of("Search", "Ring of Life", "Commune", "Stamina Boost", "Rename boat", "Teleport Boat (Pandemonium)"))
		{
			actions.put("features/" + CapeMenuTransformer.key(name), "Features / " + name);
		}
		return actions;
	}

	static List<String> knownActions()
	{
		TreeSet<String> actions = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		actions.add("Home");
		for (MenuLayout.Entry entry : MenuLayout.defaults().all())
		{
			if (!entry.isGroup()) { actions.add(entry.destination); }
		}
		actions.add("Spellbook");
		actions.add("Features");
		for (Map.Entry<String, String> utility : utilityActions().entrySet())
		{
			if (utility.getKey().contains("/")) { actions.add(utility.getValue()); }
		}
		return new ArrayList<>(actions);
	}
}

package com.capemenuorganizer;

import java.util.Locale;
import net.runelite.client.util.Text;

/** Known naming differences between the inventory and worn cape's native menus. */
final class CapeActionNames
{
	private CapeActionNames()
	{
	}

	static String canonical(String name)
	{
		String plain = Text.removeTags(name).trim();
		switch (plain.toLowerCase(Locale.ROOT))
		{
			case "carnivorous chinchompas":
			case "feldip hills":
				return "Feldip Hills";
			case "warriors' guild":
			case "warrior's guild":
				return "Warrior's Guild";
			default:
				return plain;
		}
	}

	static String key(String name)
	{
		return canonical(name).toLowerCase(Locale.ROOT);
	}
}

package com.capemenuorganizer;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.client.util.Text;

/** Plans filtering before touching native submenu arrays. Never changes an action's metadata. */
final class CapeActionVisibility
{
	final Map<String, String> catalog = new LinkedHashMap<>();
	final Map<String, MenuEntry> shortcuts = new LinkedHashMap<>();
	final Map<String, MenuEntry[]> submenus = new LinkedHashMap<>();
	final Set<MenuEntry> hiddenParents = new HashSet<>();
	private final Map<Menu, MenuEntry[]> filteredChildren = new LinkedHashMap<>();

	CapeActionVisibility(MenuEntry[] entries, CapeContext context, MenuLayout layout)
	{
		MenuEntry activeDefault = entries[entries.length - 1];
		for (MenuEntry entry : entries)
		{
			String group = CapeMenuTransformer.key(entry.getOption());
			if (!context.matches(entry) || entry.getSubMenu() == null
				|| !(group.equals("spellbook") || group.equals("features")))
			{
				continue;
			}
			String groupName = Text.removeTags(entry.getOption()).trim();
			catalog.put(group, groupName);
			List<MenuEntry> retained = new ArrayList<>();
			boolean allRecognized = true;
			for (MenuEntry child : entry.getSubMenu().getMenuEntries())
			{
				boolean recognized = child.getSubMenu() == null && context.matches(child)
					&& (child.getType() == MenuAction.CC_OP || child.getType() == MenuAction.CC_OP_LOW_PRIORITY);
				String childName = Text.removeTags(child.getOption()).trim();
				String path = group + "/" + CapeMenuTransformer.key(childName);
				if (recognized && !childName.isEmpty() && path.length() <= 120)
				{
					catalog.put(path, groupName + " / " + childName);
					shortcuts.put(groupName + " / " + childName, child);
				}
				else
				{
					recognized = false;
					allRecognized = false;
				}
				if (!recognized || !layout.hiddenActions.contains(path)) { retained.add(child); }
			}
			if (allRecognized && !retained.isEmpty())
			{
				shortcuts.put(groupName, entry);
				submenus.put(groupName, retained.toArray(new MenuEntry[0]));
			}
			// Keep core's active click choice intact, including a submenu selected as default.
			if (entry == activeDefault) { continue; }
			if (layout.hiddenActions.contains(group) || retained.isEmpty())
			{
				hiddenParents.add(entry);
			}
			else if (retained.size() != entry.getSubMenu().getMenuEntries().length)
			{
				filteredChildren.put(entry.getSubMenu(), retained.toArray(new MenuEntry[0]));
			}
		}
	}

	void apply()
	{
		filteredChildren.forEach(Menu::setMenuEntries);
	}
}

package com.capemenuorganizer;

import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;

final class CapeContext
{
	final String name;
	final int widgetId;
	final int slot;

	CapeContext(String name, int widgetId, int slot)
	{
		this.name = name;
		this.widgetId = widgetId;
		this.slot = slot;
	}

	boolean matches(MenuEntry entry)
	{
		return entry.getParam1() == widgetId && entry.getParam0() == slot;
	}

	static CapeContext detect(MenuEntry[] entries)
	{
		CapeContext result = null;
		for (MenuEntry entry : entries)
		{
			if (entry.getSubMenu() == null || !CapeMenuTransformer.isOriginalGroup(entry.getOption()))
			{
				continue;
			}
			Widget widget = entry.getWidget();
			if (widget == null)
			{
				continue;
			}
			int group = WidgetUtil.componentToInterface(widget.getId());
			String context;
			int itemId;
			if (group == InterfaceID.INVENTORY)
			{
				context = "inventory";
				itemId = widget.getItemId();
			}
			else if (group == InterfaceID.WORNITEMS)
			{
				context = "worn";
				Widget item = widget.getChild(1);
				itemId = item == null ? -1 : item.getItemId();
			}
			else
			{
				continue;
			}
			if (itemId != ItemID.SKILLCAPE_MAX && itemId != ItemID.SKILLCAPE_MAX_WORN)
			{
				continue;
			}
			if (result != null && (!result.name.equals(context) || !result.matches(entry)))
			{
				return null;
			}
			result = new CapeContext(context, entry.getParam1(), entry.getParam0());
		}
		return result;
	}
}

package com.capemenuorganizer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(CapeMenuOrganizerConfig.GROUP)
public interface CapeMenuOrganizerConfig extends Config
{
	String GROUP = "cape-menu-organizer";

	@ConfigItem(keyName = "showSidebar", name = "Show sidebar", description = "Show the menu editor in the sidebar. Custom cape menus stay active when hidden.")
	default boolean showSidebar()
	{
		return true;
	}

	@ConfigItem(keyName = "layout", name = "Layout", description = "Edited through the Cape Menu Organizer sidebar", hidden = true)
	default String layout()
	{
		return "";
	}

	@ConfigItem(keyName = "menus", name = "Normal and Shift layouts", description = "Edited through the Cape Menu Organizer sidebar", hidden = true)
	default String menus()
	{
		return "";
	}
}

package com.capemenuorganizer;

import com.google.gson.Gson;
import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.PostMenuSort;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.util.AsyncBufferedImage;

@Slf4j
@PluginDescriptor(name = "Cape Menu Organizer", description = "Organize max cape teleport menus", tags = {"cape", "teleport", "menu"})
public class CapeMenuOrganizerPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ConfigManager configManager;
	@Inject private ClientToolbar toolbar;
	@Inject private Gson gson;
	@Inject private ColorPickerManager colorPickerManager;
	@Inject private ItemManager itemManager;
	@Inject private CapeMenuOrganizerConfig config;
	private final CapeMenuTransformer transformer = new CapeMenuTransformer();
	private volatile LayoutState state;
	private volatile CapeMenusPanel panel;
	private volatile NavigationButton navigation;
	private volatile boolean running;
	private LayoutCodec codec;

	@Override
	protected void startUp()
	{
		codec = new LayoutCodec(gson);
		state = new LayoutState(codec);
		running = true;
		reload();
		LayoutState activeState = state;
		AsyncBufferedImage capeIcon = itemManager.getImage(ItemID.SKILLCAPE_MAX);
		onEdt(() ->
		{
			if (!running || state != activeState) { return; }
			panel = new CapeMenusPanel(codec, colorPickerManager);
			capeIcon.onLoaded(() -> onEdt(() ->
			{
				if (!running || state != activeState) { return; }
				navigation = NavigationButton.builder().tooltip("Cape Menu Organizer").icon(capeIcon).panel(panel).priority(7).build();
				updateNavigation();
			}));
			refresh("");
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		NavigationButton oldNavigation = navigation;
		CapeMenusPanel oldPanel = panel;
		navigation = null;
		panel = null;
		onEdt(() ->
		{
			if (oldPanel != null) { oldPanel.closeColorPicker(); }
			if (oldNavigation != null) { toolbar.removeNavigation(oldNavigation); }
		});
	}

	@Subscribe(priority = -1)
	public void onMenuOpened(MenuOpened event)
	{
		observeMenu(true);
	}

	@Subscribe(priority = -2)
	public void onPostMenuSort(PostMenuSort event)
	{
		if (!client.isMenuOpen()) { observeMenu(false); }
	}

	private void observeMenu(boolean applyLayout)
	{
		LayoutState active = state;
		if (!running || active == null) { return; }
		LayoutState.Snapshot snapshot = active.current();
		if (snapshot == null || snapshot.menus == null || snapshot.profileId != configManager.getProfile().getId()) { return; }
		Menu menu = client.getMenu();
		CapeContext context = CapeContext.detect(menu.getMenuEntries());
		if (context == null) { return; }
		try
		{
			boolean shiftPressed = client.isKeyPressed(KeyCode.KC_SHIFT);
			MenuLayout selected = snapshot.menus.forShift(shiftPressed);
			CapeMenuTransformer.Result result = applyLayout ? transformer.transform(menu, selected, context)
				: transformer.discover(menu, selected, context);
			boolean learned = active.observe(snapshot, result.destinations);
			learned |= active.observeActions(snapshot, result.capeActions);
			if (applyLayout || learned) { refresh(applyLayout && !result.changed ? result.status : ""); }
		}
		catch (IllegalArgumentException ex)
		{
			log.debug("Cape menu layout was not applied", ex);
			refresh("Layout could not be applied. See the debug log for details.");
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CapeMenuOrganizerConfig.GROUP.equals(event.getGroup()) && "showSidebar".equals(event.getKey()))
		{
			updateNavigation();
		}
		if (CapeMenuOrganizerConfig.GROUP.equals(event.getGroup())
			&& ("layout".equals(event.getKey()) || "menus".equals(event.getKey()))) { reload(); }
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		reload();
	}

	private void reload()
	{
		LayoutState active = state;
		if (!running || active == null) { return; }
		synchronized (configManager)
		{
			active.reload(configManager.getProfile().getId(), configManager.getConfiguration(CapeMenuOrganizerConfig.GROUP, "layout"),
				configManager.getConfiguration(CapeMenuOrganizerConfig.GROUP, "menus"));
		}
		refresh("");
		updateNavigation();
	}

	private void updateNavigation()
	{
		onEdt(() ->
		{
			if (!running || navigation == null) { return; }
			if (config.showSidebar()) { toolbar.addNavigation(navigation); }
			else
			{
				if (panel != null) { panel.closeColorPicker(); }
				toolbar.removeNavigation(navigation);
			}
		});
	}

	private void refresh(String message)
	{
		LayoutState active = state;
		LayoutState.Snapshot snapshot = active == null ? null : active.current();
		if (snapshot == null) { return; }
		onEdt(() ->
		{
			CapeMenusPanel editor = panel;
			if (!running || editor == null || state != active || active.current() != snapshot) { return; }
			editor.showLayouts(snapshot.menus,
				active.catalog(snapshot), active.capeActions(snapshot),
				snapshot.error == null ? message : snapshot.error, snapshot.menus != null,
				(shift, value) -> save(active, snapshot, value, false, shift),
				shift -> save(active, snapshot, MenuLayout.defaults(), true, shift),
				fromShift -> copy(active, snapshot, fromShift));
		});
	}

	private void copy(LayoutState active, LayoutState.Snapshot expected, boolean fromShift)
	{
		try
		{
			synchronized (configManager)
			{
				if (!running || state != active) { return; }
				String json = active.prepareCopy(expected, configManager.getProfile().getId(), fromShift);
				configManager.setConfiguration(CapeMenuOrganizerConfig.GROUP, "menus", json);
				reload();
			}
		}
		catch (IllegalArgumentException ex) { refresh(ex.getMessage()); }
	}

	private void save(LayoutState active, LayoutState.Snapshot expected, MenuLayout value, boolean reset, boolean shift)
	{
		try
		{
			synchronized (configManager)
			{
				if (!running || state != active) { return; }
				String json = active.prepareSave(expected, value, configManager.getProfile().getId(), reset, shift);
				configManager.setConfiguration(CapeMenuOrganizerConfig.GROUP, "menus", json);
				// Also refresh when the encoded value was unchanged and no ConfigChanged event fired.
				reload();
			}
		}
		catch (IllegalArgumentException ex)
		{
			refresh(ex.getMessage());
		}
	}

	private static void onEdt(Runnable action)
	{
		if (SwingUtilities.isEventDispatchThread()) { action.run(); }
		else { SwingUtilities.invokeLater(action); }
	}

	@Provides
	CapeMenuOrganizerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CapeMenuOrganizerConfig.class);
	}
}

package com.capemenuorganizer;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.event.WindowEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTree;
import javax.swing.tree.DefaultMutableTreeNode;
import javax.swing.tree.DefaultTreeModel;
import javax.swing.tree.DefaultTreeCellRenderer;
import javax.swing.tree.TreePath;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;

/** Swing state belongs to the EDT; saved changes are passed out as independent copies. */
final class CapeMenuPanel extends PluginPanel
{
	private final LayoutCodec codec;
	private final ColorPickerManager colorPickerManager;
	private RuneliteColorPicker activeColorPicker;
	private final JTree tree = new JTree();
	private final JComboBox<String> destinations = new JComboBox<>();
	private final JTextArea status = text("");
	private final JPanel controls = new JPanel(new GridLayout(0, 2, 4, 4));
	private final JPanel visibility = new JPanel();
	private final JPanel capeVisibility = new JPanel();
	private final JButton copyButton = new JButton();
	private Runnable copy = () -> {};
	private final List<JButton> editButtons = new ArrayList<>();
	private MenuLayout layout = new MenuLayout();
	private Consumer<MenuLayout> save = value -> {};
	private Runnable reset = () -> {};
	private boolean editable;
	private boolean refreshing;
	private long editorSession;

	CapeMenuPanel(LayoutCodec codec, ColorPickerManager colorPickerManager)
	{
		this.codec = codec;
		this.colorPickerManager = colorPickerManager;
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 8, 10, 8));
		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		JLabel title = new JLabel("Cape Menu Organizer");
		title.setFont(FontManager.getRunescapeBoldFont());
		content.add(title);
		content.add(text("Applies to inventory and worn cape. Saves automatically."));
		JScrollPane scroll = new JScrollPane(tree);
		scroll.setPreferredSize(new Dimension(200, 260));
		scroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 360));
		content.add(scroll);
		tree.setRootVisible(true);
		tree.setShowsRootHandles(true);
		tree.setCellRenderer(new DefaultTreeCellRenderer()
		{
			@Override
			public Component getTreeCellRendererComponent(JTree owner, Object value, boolean selected,
				boolean expanded, boolean leaf, int row, boolean focus)
			{
				super.getTreeCellRendererComponent(owner, value, selected, expanded, leaf, row, focus);
				Object entry = ((DefaultMutableTreeNode) value).getUserObject();
				if (!selected && entry instanceof MenuLayout.Entry && ((MenuLayout.Entry) entry).color != null)
				{
					setForeground(new Color(((MenuLayout.Entry) entry).color));
				}
				return this;
			}
		});
		content.add(destinations);
		addButton("Add action", () ->
		{
			String destination = (String) destinations.getSelectedItem();
			if (destination != null)
			{
				String group = selectedGroup();
				edit(next -> next.addTeleport(group, destination));
			}
		});
		addButton("Add group", () ->
		{
			String name = promptForCurrentLayout(() -> JOptionPane.showInputDialog(this, "Group name:", "New group", JOptionPane.PLAIN_MESSAGE));
			if (name != null) { edit(next -> next.addGroup(name)); }
		});
		addButton("Rename", () ->
		{
			MenuLayout.Entry selected = selected();
			if (selected == null || !selected.isGroup()) { return; }
			String name = promptForCurrentLayout(() -> JOptionPane.showInputDialog(this, "Group name:", selected.name));
			if (name != null) { edit(next -> next.rename(selected.id, name)); }
		});
		addButton("Remove", () ->
		{
			MenuLayout.Entry selected = selected();
			if (selected == null) { return; }
			if (selected.isGroup() && !selected.children.isEmpty() && !Integer.valueOf(JOptionPane.OK_OPTION).equals(promptForCurrentLayout(() -> JOptionPane.showConfirmDialog(this,
				"Remove this group and its shortcuts?", "Remove group", JOptionPane.OK_CANCEL_OPTION))))
			{
				return;
			}
			edit(next -> next.remove(selected.id));
		});
		addButton("Move up", () -> moveBy(-1));
		addButton("Move down", () -> moveBy(1));
		addButton("Move to…", this::moveTo);
		addButton("Color…", () ->
		{
			MenuLayout.Entry entry = selected();
			if (entry == null) { return; }
			RuneliteColorPicker picker = colorPickerManager.create(this,
				entry.color == null ? Color.WHITE : new Color(entry.color),
				getName() == null ? entry.toString() : getName() + " - " + entry, true);
			activeColorPicker = picker;
			// Capture the save session. A modeless picker must not write to a later profile/layout.
			MenuLayout beforeColor = codec.copy(layout);
			Consumer<MenuLayout> saveSession = save;
			picker.setOnClose(color ->
			{
				if (activeColorPicker == picker) { activeColorPicker = null; }
				beforeColor.setColor(entry.id, color.getRGB() & 0xffffff);
				saveSession.accept(codec.copy(beforeColor));
			});
			picker.setLocationRelativeTo(this);
			picker.setVisible(true);
		});
		addButton("Reset color", () ->
		{
			MenuLayout.Entry entry = selected();
			if (entry != null) { edit(next -> next.setColor(entry.id, null)); }
		});
		JButton resetButton = new JButton("Reset layout");
		resetButton.setMargin(new Insets(4, 3, 4, 3));
		resetButton.addActionListener(event ->
		{
			Runnable resetSession = reset;
			String prompt = editable ? "Replace this menu's layout with defaults?"
				: "Saved menus cannot be read. Replace both Normal and Shift layouts with defaults?";
			if (JOptionPane.showConfirmDialog(this, prompt, "Reset layout",
				JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
			{
				resetSession.run();
			}
		});
		controls.add(resetButton);
		content.add(controls);
		copyButton.setMargin(new Insets(4, 3, 4, 3));
		copyButton.addActionListener(event ->
		{
			Runnable copySession = copy;
			if (JOptionPane.showConfirmDialog(this, "Replace the other menu with a copy of this one?",
				"Copy menu", JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION) { copySession.run(); }
		});
		content.add(copyButton);
		content.add(text("Select Main menu or a group, then add actions."));
		visibility.setLayout(new BoxLayout(visibility, BoxLayout.Y_AXIS));
		JLabel originalsHeading = new JLabel("Show original menus");
		originalsHeading.setFont(FontManager.getRunescapeFont());
		originalsHeading.setForeground(ColorScheme.BRAND_ORANGE);
		originalsHeading.setToolTipText("Custom shortcuts remain available when original menus are hidden.");
		originalsHeading.setBorder(BorderFactory.createEmptyBorder(18, 0, 0, 0));
		content.add(originalsHeading);
		JTextArea visibilityHelp = text("Checked = visible.");
		visibilityHelp.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));
		visibilityHelp.setRows(1);
		visibilityHelp.setMaximumSize(new Dimension(Integer.MAX_VALUE, visibilityHelp.getPreferredSize().height));
		content.add(visibilityHelp);
		content.add(new JLabel("Teleports"));
		content.add(visibility);
		content.add(new JLabel("Cape actions"));
		capeVisibility.setLayout(new BoxLayout(capeVisibility, BoxLayout.Y_AXIS));
		content.add(capeVisibility);
		content.add(status);
		for (Component child : content.getComponents())
		{
			if (child instanceof javax.swing.JComponent)
			{
				((javax.swing.JComponent) child).setAlignmentX(Component.LEFT_ALIGNMENT);
			}
		}
		add(content, BorderLayout.NORTH);
	}

	void setCopyAction(String target, boolean enabled, Runnable onCopy)
	{
		copyButton.setText("Copy to " + target);
		copyButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, copyButton.getPreferredSize().height));
		copyButton.setToolTipText("Replace " + target + " with this menu, including colors and visibility.");
		copyButton.setEnabled(enabled);
		copy = onCopy;
	}

	void showLayout(MenuLayout value, List<String> catalog, String message, boolean allowEdits,
		Consumer<MenuLayout> onSave, Runnable onReset)
	{
		showLayout(value, catalog, Collections.emptyMap(), message, allowEdits, onSave, onReset);
	}

	void showLayout(MenuLayout value, List<String> catalog, Map<String, String> capeActions,
		String message, boolean allowEdits, Consumer<MenuLayout> onSave, Runnable onReset)
	{
		editorSession++;
		layout = codec.copy(value);
		save = onSave;
		reset = onReset;
		editable = allowEdits;
		String selection = selected() == null ? null : selected().id;
		refreshTree(selection);
		Object oldDestination = destinations.getSelectedItem();
		destinations.removeAllItems();
		catalog.stream().distinct().sorted(String.CASE_INSENSITIVE_ORDER).forEach(destinations::addItem);
		if (oldDestination != null && catalog.contains(oldDestination)) { destinations.setSelectedItem(oldDestination); }
		destinations.setEnabled(allowEdits);
		for (JButton button : editButtons) { button.setEnabled(allowEdits); }
		visibility.removeAll();
		refreshing = true;
		MenuLayout.ORIGINALS.stream().sorted().forEach(original ->
		{
			String[] parts = original.split(":", 2);
			String label = "inventory".equals(parts[0]) ? "Inventory: Teleports" : "Worn: " + parts[1];
			JCheckBox checkbox = new JCheckBox(label, !layout.hiddenOriginals.contains(original));
			checkbox.setToolTipText("Show the original " + parts[1] + " submenu in " + parts[0]);
			checkbox.setEnabled(allowEdits);
			checkbox.addActionListener(event ->
			{
				if (!refreshing)
				{
					edit(next ->
					{
						if (checkbox.isSelected()) { next.hiddenOriginals.remove(original); }
						else { next.hiddenOriginals.add(original); }
					});
				}
			});
			visibility.add(checkbox);
		});
		capeVisibility.removeAll();
		Map<String, String> knownActions = new TreeMap<>(capeActions);
		knownActions.put("spellbook", "Spellbook");
		knownActions.put("features", "Features");
		for (Map.Entry<String, String> action : knownActions.entrySet())
		{
			String path = action.getKey();
			boolean parent = path.indexOf('/') < 0;
			String group = parent ? path : path.substring(0, path.indexOf('/'));
			String label = parent ? "Show " + action.getValue() : action.getValue().substring(action.getValue().indexOf(" / ") + 3);
			if ("features/teleport boat (pandemonium)".equals(path)) { label = "Teleport Boat"; }
			String display = label.length() > 24 ? "<html><body style='width:140px'>"
				+ label.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;") + "</body></html>" : label;
			JCheckBox checkbox = new JCheckBox(display, !layout.hiddenActions.contains(path));
			checkbox.setBorder(BorderFactory.createEmptyBorder(2, parent ? 0 : 14, 2, 0));
			checkbox.setToolTipText(action.getValue());
			checkbox.setEnabled(allowEdits && (parent || !layout.hiddenActions.contains(group)));
			checkbox.addActionListener(event ->
			{
				if (!refreshing)
				{
					edit(next ->
					{
						if (checkbox.isSelected()) { next.hiddenActions.remove(path); }
						else { next.hiddenActions.add(path); }
					});
				}
			});
			capeVisibility.add(checkbox);
		}
		refreshing = false;
		setStatus(message);
		revalidate();
		repaint();
	}

	void setStatus(String message)
	{
		status.setText(message);
		status.setRows(Math.max(1, ((message == null ? 0 : message.length()) + 26) / 27));
		status.setMaximumSize(new Dimension(Integer.MAX_VALUE, status.getPreferredSize().height));
		status.setVisible(message != null && !message.isEmpty());
	}

	<T> T promptForCurrentLayout(Supplier<T> prompt)
	{
		long session = editorSession;
		T result = prompt.get();
		if (session != editorSession)
		{
			setStatus("The menu changed while the dialog was open. Try again.");
			return null;
		}
		return result;
	}

	void closeColorPicker()
	{
		RuneliteColorPicker picker = activeColorPicker;
		activeColorPicker = null;
		if (picker != null)
		{
			picker.setOnClose(null);
			picker.dispatchEvent(new WindowEvent(picker, WindowEvent.WINDOW_CLOSING));
		}
	}

	private static JTextArea text(String value)
	{
		JTextArea area = new JTextArea(value);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setEditable(false);
		area.setOpaque(false);
		area.setBorder(BorderFactory.createEmptyBorder(6, 0, 8, 0));
		area.setFocusable(false);
		area.setColumns(20);
		area.setRows(Math.max(1, (value.length() + 26) / 27));
		area.setMaximumSize(new Dimension(Integer.MAX_VALUE, area.getPreferredSize().height));
		return area;
	}

	private void addButton(String name, Runnable action)
	{
		JButton button = new JButton(name);
		button.setMargin(new Insets(4, 3, 4, 3));
		button.addActionListener(event -> action.run());
		controls.add(button);
		editButtons.add(button);
	}

	private void edit(Consumer<MenuLayout> action)
	{
		if (!editable) { return; }
		try
		{
			MenuLayout next = codec.copy(layout);
			action.accept(next);
			next.validate();
			String selection = selected() == null ? null : selected().id;
			layout = next;
			save.accept(codec.copy(next));
			refreshTree(selection);
		}
		catch (IllegalArgumentException ex)
		{
			setStatus(ex.getMessage());
		}
	}

	private void refreshTree(String selectedId)
	{
		DefaultMutableTreeNode root = new DefaultMutableTreeNode("Main menu");
		DefaultMutableTreeNode select = root;
		for (MenuLayout.Entry entry : layout.entries)
		{
			DefaultMutableTreeNode node = new DefaultMutableTreeNode(entry);
			root.add(node);
			if (entry.id.equals(selectedId)) { select = node; }
			for (MenuLayout.Entry child : entry.children)
			{
				DefaultMutableTreeNode nested = new DefaultMutableTreeNode(child);
				node.add(nested);
				if (child.id.equals(selectedId)) { select = nested; }
			}
		}
		tree.setModel(new DefaultTreeModel(root));
		for (int row = 0; row < tree.getRowCount(); row++) { tree.expandRow(row); }
		tree.setSelectionPath(new TreePath(select.getPath()));
	}

	private MenuLayout.Entry selected()
	{
		Object node = tree.getLastSelectedPathComponent();
		if (!(node instanceof DefaultMutableTreeNode)) { return null; }
		Object value = ((DefaultMutableTreeNode) node).getUserObject();
		return value instanceof MenuLayout.Entry ? (MenuLayout.Entry) value : null;
	}

	private String selectedGroup()
	{
		MenuLayout.Entry entry = selected();
		if (entry == null) { return null; }
		if (entry.isGroup()) { return entry.id; }
		for (MenuLayout.Entry root : layout.entries)
		{
			if (root.children.contains(entry)) { return root.id; }
		}
		return null;
	}

	private void moveBy(int delta)
	{
		MenuLayout.Entry entry = selected();
		if (entry == null) { return; }
		List<MenuLayout.Entry> parent = layout.parent(entry.id);
		int index = parent.indexOf(entry) + delta;
		if (index >= 0 && index < parent.size())
		{
			String groupId = selectedGroup();
			if (entry.isGroup()) { groupId = null; }
			String target = groupId;
			edit(next -> next.move(entry.id, target, index));
		}
	}

	private void moveTo()
	{
		MenuLayout.Entry entry = selected();
		if (entry == null || entry.isGroup()) { return; }
		List<MenuLayout.Entry> groups = new ArrayList<>();
		groups.add(MenuLayout.Entry.group("Main menu"));
		for (MenuLayout.Entry root : layout.entries) { if (root.isGroup()) { groups.add(root); } }
		Object chosen = promptForCurrentLayout(() -> JOptionPane.showInputDialog(this, "Move shortcut to:", "Move shortcut",
			JOptionPane.PLAIN_MESSAGE, null, groups.toArray(), groups.get(0)));
		if (chosen == null) { return; }
		String groupId = chosen == groups.get(0) ? null : ((MenuLayout.Entry) chosen).id;
		edit(next -> next.move(entry.id, groupId, Integer.MAX_VALUE));
	}
}

package com.capemenuorganizer;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.client.util.Text;

/** Copies current native actions only. No stored action IDs or synthetic dispatch. */
final class CapeMenuTransformer
{
	private static final Set<String> GROUP_NAMES = Set.of("teleports", "guild teleports", "skilling areas", "poh portals");
	private static final Set<String> ROOT_TELEPORTS = Set.of("home", "crafting guild");
	private static final int MAX_SUBMENU_ENTRIES = 64;

	static final class Result
	{
		final boolean changed;
		final List<String> destinations;
		final Map<String, String> capeActions;
		final String status;

		Result(boolean changed, List<String> destinations, String status)
		{
			this(changed, destinations, Collections.emptyMap(), status);
		}

		Result(boolean changed, List<String> destinations, Map<String, String> capeActions, String status)
		{
			this.changed = changed;
			this.destinations = destinations;
			this.capeActions = capeActions;
			this.status = status;
		}
	}

	static String key(String text)
	{
		return Text.removeTags(text).trim().toLowerCase(Locale.ROOT);
	}

	static boolean isOriginalGroup(String option)
	{
		return GROUP_NAMES.contains(key(option));
	}

	Result discover(Menu menu, MenuLayout layout, CapeContext context)
	{
		MenuEntry[] original = menu.getMenuEntries();
		if (context == null || original.length == 0) { return unchanged("No cape menu to inspect."); }
		Map<String, Action> observed = new LinkedHashMap<>();
		for (MenuEntry entry : original)
		{
			if (context.matches(entry) && entry.getSubMenu() != null && isOriginalGroup(entry.getOption()))
			{
				if (!collect(entry.getSubMenu(), context, observed, 0))
				{
					return unchanged("Unrecognized native cape menu; editor choices retained.");
				}
			}
		}
		if (observed.isEmpty()) { return unchanged("No native teleport actions found."); }
		List<String> catalog = new ArrayList<>();
		for (Action action : observed.values()) { catalog.add(action.reference); }
		for (MenuEntry entry : original)
		{
			if (context.matches(entry) && entry.getSubMenu() == null && nativeAction(entry)
				&& ROOT_TELEPORTS.contains(key(entry.getOption())))
			{
				catalog.add(CapeActionNames.canonical(entry.getOption()));
			}
		}
		CapeActionVisibility utilities = new CapeActionVisibility(original, context, layout);
		catalog.addAll(utilities.shortcuts.keySet());
		return new Result(false, catalog, utilities.catalog, "Cape actions refreshed. Ready to edit.");
	}

	Result transform(Menu menu, MenuLayout layout, CapeContext context)
	{
		MenuEntry[] original = menu.getMenuEntries();
		Map<String, Action> actions = new LinkedHashMap<>();
		Set<MenuEntry> teleportRoots = new HashSet<>();
		if (context == null || original.length == 0)
		{
			return unchanged("Open the max cape menu in inventory or equipment.");
		}
		for (MenuEntry entry : original)
		{
			if (context.matches(entry) && entry.getSubMenu() != null && isOriginalGroup(entry.getOption()))
			{
				if (!collect(entry.getSubMenu(), context, actions, 0))
				{
					return unchanged("Unrecognized teleport action; original menu retained.");
				}
				teleportRoots.add(entry);
			}
		}
		if (actions.isEmpty())
		{
			return unchanged("No native cape teleport submenu found; original menu retained.");
		}
		for (MenuEntry entry : original)
		{
			if (context.matches(entry) && entry.getSubMenu() == null && nativeAction(entry)
				&& ROOT_TELEPORTS.contains(key(entry.getOption())))
			{
				actions.putIfAbsent(key(entry.getOption()), new Action(entry));
				teleportRoots.add(entry);
			}
		}
		layout.validate();
		MenuEntry defaultEntry = original[original.length - 1];
		CapeActionVisibility utilityVisibility = new CapeActionVisibility(original, context, layout);
		for (Map.Entry<String, MenuEntry> shortcut : utilityVisibility.shortcuts.entrySet())
		{
			List<Action> children = null;
			MenuEntry[] submenu = utilityVisibility.submenus.get(shortcut.getKey());
			if (submenu != null)
			{
				children = new ArrayList<>();
				for (MenuEntry child : submenu) { children.add(new Action(child)); }
			}
			actions.put(CapeActionNames.key(shortcut.getKey()), new Action(shortcut.getValue(), shortcut.getKey(), children));
		}
		// Count native submenu copies too: one reference may create several actual entries.
		int totalEntries = count(menu, 0);
		for (MenuLayout.Entry entry : layout.entries)
		{
			if (entry.isGroup())
			{
				int childCount = 0;
				int directChildren = 0;
				for (MenuLayout.Entry child : entry.children)
				{
					Action action = actions.get(CapeActionNames.key(child.destination));
					if (action != null)
					{
						directChildren++;
						childCount += action.entryCount();
					}
				}
				if (directChildren > MAX_SUBMENU_ENTRIES)
				{
					return unchanged("A group exceeds 64 actions; original menu retained. Split it into smaller groups.");
				}
				if (childCount > 0) { totalEntries += 1 + childCount; }
			}
			else
			{
				Action action = actions.get(CapeActionNames.key(entry.destination));
				if (action != null && !action.matchesNativeEntry(defaultEntry, context)) { totalEntries += action.entryCount(); }
			}
		}
		if (totalEntries > 450) { return unchanged("Menu is too large; original menu retained."); }
		List<MenuEntry> retained = new ArrayList<>();
		for (MenuEntry entry : original)
		{
			boolean hide = teleportRoots.contains(entry) && (entry.getSubMenu() == null
				|| layout.hiddenOriginals.contains(context.name + ":" + key(entry.getOption())));
			hide |= utilityVisibility.hiddenParents.contains(entry);
			if (!hide || entry == defaultEntry)
			{
				retained.add(entry);
			}
		}
		List<MenuEntry> customDisplayOrder = new ArrayList<>();
		for (MenuLayout.Entry entry : layout.entries)
		{
			if (entry.isGroup())
			{
				List<Action> group = new ArrayList<>();
				for (MenuLayout.Entry child : entry.children)
				{
					Action action = actions.get(CapeActionNames.key(child.destination));
					if (action != null)
					{
						group.add(action);
					}
				}
				if (!group.isEmpty())
				{
					List<Integer> colors = new ArrayList<>();
					for (MenuLayout.Entry child : entry.children)
					{
						if (actions.containsKey(CapeActionNames.key(child.destination))) { colors.add(child.color); }
					}
					customDisplayOrder.add(addGroup(menu, colored(entry.name, entry.color), group, colors));
				}
			}
			else
			{
				Action action = actions.get(CapeActionNames.key(entry.destination));
				if (action != null && !action.matchesNativeEntry(defaultEntry, context))
				{
					customDisplayOrder.add(action.copyTo(menu, entry.color));
				}
			}
		}
		// Menu arrays are reversed. Insert custom entries below the untouched active default.
		Collections.reverse(customDisplayOrder);
		retained.addAll(Math.max(0, retained.size() - 1), customDisplayOrder);
		utilityVisibility.apply();
		menu.setMenuEntries(retained.toArray(new MenuEntry[0]));
		List<String> catalog = new ArrayList<>();
		for (Action action : actions.values())
		{
			catalog.add(action.reference);
		}
		catalog.sort(String.CASE_INSENSITIVE_ORDER);
		return new Result(true, catalog, utilityVisibility.catalog,
			"Layout applied to " + context.name + " cape (" + catalog.size() + " available actions).");
	}

	private static Result unchanged(String reason)
	{
		return new Result(false, Collections.emptyList(), reason);
	}

	private static boolean nativeAction(MenuEntry entry)
	{
		return entry.getType() == MenuAction.CC_OP || entry.getType() == MenuAction.CC_OP_LOW_PRIORITY;
	}

	private static boolean collect(Menu menu, CapeContext context, Map<String, Action> actions, int depth)
	{
		if (depth > 3 || menu.getMenuEntries().length == 0)
		{
			return false;
		}
		for (MenuEntry entry : menu.getMenuEntries())
		{
			if (entry.getSubMenu() != null)
			{
				if (!collect(entry.getSubMenu(), context, actions, depth + 1))
				{
					return false;
				}
				continue;
			}
			if (!context.matches(entry) || !nativeAction(entry) || entry.getIdentifier() <= 0)
			{
				return false;
			}
			String name = Text.removeTags(entry.getOption()).trim();
			if (name.isEmpty() || name.length() > 100 || name.indexOf('<') >= 0 || name.indexOf('>') >= 0)
			{
				return false;
			}
			Action action = new Action(entry);
			Action previous = actions.putIfAbsent(CapeActionNames.key(name), action);
			if (previous != null && !previous.sameOperation(action))
			{
				return false;
			}
			if (actions.size() > 100)
			{
				return false;
			}
		}
		return true;
	}

	private static int count(Menu menu, int depth)
	{
		if (depth > 5)
		{
			return 1000;
		}
		int count = 0;
		for (MenuEntry entry : menu.getMenuEntries())
		{
			count++;
			if (entry.getSubMenu() != null)
			{
				count += count(entry.getSubMenu(), depth + 1);
			}
		}
		return count;
	}

	private static String colored(String name, Integer color)
	{
		return color == null ? name : String.format(Locale.ROOT, "<col=%06x>%s</col>", color, name);
	}

	private static MenuEntry addGroup(Menu menu, String name, List<Action> actions, List<Integer> colors)
	{
		MenuEntry parent = menu.createMenuEntry(-1).setOption(name).setTarget(actions.get(0).target).setType(MenuAction.RUNELITE);
		Menu sub = parent.createSubMenu();
		for (int i = actions.size() - 1; i >= 0; i--)
		{
			actions.get(i).copyTo(sub, colors.get(i));
		}
		return parent;
	}

	private static final class Action
	{
		private final String option, target, reference;
		private final List<Action> children;
		private final int identifier, param0, param1, itemId, worldViewId;
		private final MenuAction type;
		private final boolean forceLeftClick, deprioritized;
		private final Consumer<MenuEntry> callback;

		Action(MenuEntry source)
		{
			this(source, CapeActionNames.canonical(source.getOption()), null);
		}

		Action(MenuEntry source, String reference, List<Action> children)
		{
			option = CapeActionNames.canonical(source.getOption());
			this.reference = reference;
			this.children = children;
			target = source.getTarget();
			identifier = source.getIdentifier();
			param0 = source.getParam0();
			param1 = source.getParam1();
			itemId = source.getItemId();
			worldViewId = source.getWorldViewId();
			type = source.getType();
			forceLeftClick = source.isForceLeftClick();
			deprioritized = source.isDeprioritized();
			callback = source.onClick();
		}

		boolean sameOperation(Action other)
		{
			return identifier == other.identifier && param0 == other.param0 && param1 == other.param1
				&& itemId == other.itemId && type == other.type && callback == other.callback;
		}

		int entryCount()
		{
			int count = 1;
			if (children != null)
			{
				for (Action child : children) { count += child.entryCount(); }
			}
			return count;
		}

		boolean matchesNativeEntry(MenuEntry entry, CapeContext context)
		{
			if (children != null || entry.getSubMenu() != null || !context.matches(entry) || !nativeAction(entry)
				|| callback != entry.onClick() || worldViewId != entry.getWorldViewId()
				|| !CapeActionNames.key(option).equals(CapeActionNames.key(entry.getOption())))
			{
				return false;
			}
			// Home/Crafting Guild also have direct native ops distinct from submenu ops.
			return ROOT_TELEPORTS.contains(CapeActionNames.key(reference))
				|| (identifier == entry.getIdentifier() && itemId == entry.getItemId());
		}

		MenuEntry copyTo(Menu menu, Integer color)
		{
			MenuEntry copy = menu.createMenuEntry(-1).setOption(colored(option, color)).setTarget(target).setIdentifier(identifier)
				.setParam0(param0).setParam1(param1).setItemId(itemId).setWorldViewId(worldViewId)
				.setType(type).setForceLeftClick(forceLeftClick).setDeprioritized(deprioritized).onClick(callback);
			if (children != null)
			{
				copy.setType(MenuAction.RUNELITE).onClick(null);
				Menu submenu = copy.createSubMenu();
				for (Action child : children) { child.copyTo(submenu, null); }
			}
			return copy;
		}
	}
}

package com.capemenuorganizer;

import java.awt.BorderLayout;
import java.util.List;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.swing.JTabbedPane;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;

/** Tab choice controls editing only; the actual Shift key selects the in-game layout. */
final class CapeMenusPanel extends PluginPanel
{
	private final LayoutCodec codec;
	private final CapeMenuPanel normal;
	private final CapeMenuPanel shift;

	CapeMenusPanel(LayoutCodec codec, ColorPickerManager colorPickerManager)
	{
		this.codec = codec;
		normal = new CapeMenuPanel(codec, colorPickerManager);
		shift = new CapeMenuPanel(codec, colorPickerManager);
		normal.setName("Normal");
		shift.setName("Shift");
		JTabbedPane tabs = new JTabbedPane();
		tabs.addTab("Normal", normal);
		tabs.addTab("Shift", shift);
		setLayout(new BorderLayout());
		add(tabs, BorderLayout.NORTH);
	}

	void showLayouts(MenuLayouts menus, List<String> catalog, Map<String, String> capeActions,
		String message, boolean editable, BiConsumer<Boolean, MenuLayout> save, Consumer<Boolean> reset)
	{
		showLayouts(menus, catalog, capeActions, message, editable, save, reset, fromShift ->
		{
			if (menus != null) { save.accept(!fromShift, codec.copy(menus.forShift(fromShift))); }
		});
	}

	void showLayouts(MenuLayouts menus, List<String> catalog, Map<String, String> capeActions,
		String message, boolean editable, BiConsumer<Boolean, MenuLayout> save, Consumer<Boolean> reset, Consumer<Boolean> copy)
	{
		MenuLayouts displayed = menus == null ? codec.loadMenus(null, null) : menus;
		normal.showLayout(displayed.normal, catalog, capeActions, message, editable,
			value -> save.accept(false, value), () -> reset.accept(false));
		shift.showLayout(displayed.shift, catalog, capeActions, message, editable,
			value -> save.accept(true, value), () -> reset.accept(true));
		normal.setCopyAction("Shift", editable, () -> copy.accept(false));
		shift.setCopyAction("Normal", editable, () -> copy.accept(true));
	}

	void closeColorPicker()
	{
		normal.closeColorPicker();
		shift.closeColorPicker();
	}
}

package com.capemenuorganizer;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;

final class LayoutCodec
{
	private final Gson gson;

	LayoutCodec(Gson gson)
	{
		this.gson = gson;
	}

	MenuLayout decode(String json)
	{
		if (json == null || json.length() > 64000)
		{
			throw new IllegalArgumentException("Layout is missing or too large.");
		}
		try
		{
			JsonElement parsed = gson.fromJson(json, JsonElement.class);
			if (parsed == null || !parsed.isJsonObject())
			{
				throw new IllegalArgumentException("Invalid layout configuration.");
			}
			JsonObject object = parsed.getAsJsonObject();
			if (!object.has("version") || !object.has("entries"))
			{
				throw new IllegalArgumentException("Layout version or entries are missing.");
			}
			MenuLayout layout = gson.fromJson(object, MenuLayout.class);
			layout.validate();
			for (MenuLayout.Entry entry : layout.all())
			{
				if (!entry.isGroup()) { entry.destination = CapeActionNames.canonical(entry.destination); }
			}
			return layout;
		}
		catch (JsonParseException | IllegalStateException ex)
		{
			throw new IllegalArgumentException("Cannot read the saved layout.", ex);
		}
	}

	String encode(MenuLayout layout)
	{
		layout.validate();
		return gson.toJson(layout);
	}

	MenuLayout copy(MenuLayout layout)
	{
		return decode(encode(layout));
	}

	MenuLayouts loadMenus(String legacy, String paired)
	{
		if (paired == null || paired.isEmpty())
		{
			MenuLayout original = legacy == null || legacy.isEmpty() ? MenuLayout.defaults() : decode(legacy);
			return new MenuLayouts(original, copy(original));
		}
		if (paired.length() > 128000) { throw new IllegalArgumentException("Saved menus are too large."); }
		try
		{
			JsonElement parsed = gson.fromJson(paired, JsonElement.class);
			if (parsed == null || !parsed.isJsonObject()) { throw new IllegalArgumentException("Invalid saved menus."); }
			JsonObject object = parsed.getAsJsonObject();
			JsonElement version = object.get("version");
			if (version == null || !version.isJsonPrimitive() || !version.getAsJsonPrimitive().isNumber()
				|| !"1".equals(version.getAsString()) || !object.has("normal") || !object.has("shift"))
			{
				throw new IllegalArgumentException("Unsupported or incomplete saved menus.");
			}
			return new MenuLayouts(decode(gson.toJson(object.get("normal"))), decode(gson.toJson(object.get("shift"))));
		}
		catch (JsonParseException | IllegalStateException ex)
		{
			throw new IllegalArgumentException("Cannot read saved menus.", ex);
		}
	}

	String encodeMenus(MenuLayouts menus)
	{
		JsonObject object = new JsonObject();
		object.addProperty("version", 1);
		object.add("normal", gson.fromJson(encode(menus.normal), JsonElement.class));
		object.add("shift", gson.fromJson(encode(menus.shift), JsonElement.class));
		String json = gson.toJson(object);
		if (json.length() > 128000) { throw new IllegalArgumentException("Saved menus are too large."); }
		return json;
	}
}

package com.capemenuorganizer;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.Set;
import java.util.TreeSet;

/** Serializes profile/editor transitions; published layouts are never mutated. */
final class LayoutState
{
	static final class Snapshot
	{
		final long profileId;
		final MenuLayouts menus;
		final String error;

		Snapshot(long profileId, MenuLayouts menus, String error)
		{
			this.profileId = profileId;
			this.menus = menus;
			this.error = error;
		}
	}

	private final LayoutCodec codec;
	private final Set<String> catalog = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
	private final Map<String, String> capeActions = new TreeMap<>();
	private volatile Snapshot current;

	LayoutState(LayoutCodec codec)
	{
		this.codec = codec;
	}

	synchronized void reload(long profileId, String legacy, String paired)
	{
		if (current == null || current.profileId != profileId)
		{
			catalog.clear();
			catalog.addAll(CapeActionCatalog.knownActions());
			capeActions.clear();
			capeActions.putAll(CapeActionCatalog.utilityActions());
		}
		try
		{
			current = new Snapshot(profileId, codec.loadMenus(legacy, paired), null);
			for (MenuLayout layout : new MenuLayout[]{current.menus.normal, current.menus.shift})
			{
				for (MenuLayout.Entry entry : layout.all())
				{
					if (!entry.isGroup()) { catalog.add(entry.destination); }
				}
			}
		}
		catch (IllegalArgumentException ex)
		{
			current = new Snapshot(profileId, null, "Saved menus could not be read. Native menus retained. Reset explicitly to restore both layouts.");
		}
	}

	Snapshot current()
	{
		return current;
	}

	synchronized String prepareCopy(Snapshot expected, long activeProfileId, boolean fromShift)
	{
		if (expected.menus == null) { throw new IllegalArgumentException("Reset unreadable menus before copying."); }
		return prepareSave(expected, expected.menus.forShift(fromShift), activeProfileId, false, !fromShift);
	}

	synchronized String prepareSave(Snapshot expected, MenuLayout value, long activeProfileId, boolean reset, boolean shift)
	{
		if (current != expected || expected.profileId != activeProfileId)
		{
			throw new IllegalArgumentException("The active profile or layout changed. Try your edit again.");
		}
		if (expected.menus == null && !reset)
		{
			throw new IllegalArgumentException("Reset explicitly to replace the unreadable saved layout.");
		}
		MenuLayouts source = expected.menus == null ? codec.loadMenus(null, null) : expected.menus;
		return codec.encodeMenus(new MenuLayouts(codec.copy(shift ? source.normal : value), codec.copy(shift ? value : source.shift)));
	}

	synchronized boolean observe(Snapshot expected, List<String> destinations)
	{
		return expected == current && catalog.addAll(destinations);
	}

	synchronized boolean observeActions(Snapshot expected, Map<String, String> observed)
	{
		if (expected != current) { return false; }
		boolean changed = false;
		for (Map.Entry<String, String> action : observed.entrySet())
		{
			if (capeActions.containsKey(action.getKey()) || capeActions.size() < 100)
			{
				String previous = capeActions.put(action.getKey(), action.getValue());
				changed |= !action.getValue().equals(previous);
			}
		}
		return changed;
	}

	synchronized Map<String, String> capeActions(Snapshot expected)
	{
		return current == expected ? new TreeMap<>(capeActions) : new TreeMap<>();
	}

	synchronized List<String> catalog(Snapshot expected)
	{
		return current == expected ? new ArrayList<>(catalog) : new ArrayList<>();
	}
}

package com.capemenuorganizer;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;

/** Persisted layout contains destination names, never executable game action data. */
final class MenuLayout
{
	static final Set<String> ORIGINALS = Set.of("inventory:teleports", "worn:guild teleports",
		"worn:skilling areas", "worn:poh portals");
	int version = 1;
	List<Entry> entries = new ArrayList<>();
	Set<String> hiddenOriginals = new LinkedHashSet<>(ORIGINALS);
	Set<String> hiddenActions = new LinkedHashSet<>();

	static final class Entry
	{
		String id = UUID.randomUUID().toString();
		String name;
		String destination;
		Integer color;
		List<Entry> children = new ArrayList<>();

		static Entry group(String name)
		{
			Entry entry = new Entry();
			entry.name = name;
			return entry;
		}

		boolean isGroup()
		{
			return destination == null;
		}

		@Override
		public String toString()
		{
			return isGroup() ? name : destination;
		}
	}

	static MenuLayout defaults()
	{
		MenuLayout layout = new MenuLayout();
		layout.defaultGroup("Poh", "Home", "Aldarin", "Brimhaven", "Hosidius", "Pollnivneach", "Prifddinas",
			"Rellekka", "Rimmington", "Taverley", "Yanille");
		layout.defaultGroup("Guild", "Crafting Guild", "Farming Guild", "Fishing Guild", "Hunter Guild", "Warrior's Guild");
		layout.defaultGroup("Skill", "Black chinchompas", "Boat", "Feldip Hills", "Last Boat", "Otto's Grotto", "The Pandemonium");
		return layout;
	}

	private void defaultGroup(String name, String... actions)
	{
		Entry group = addGroup(name);
		for (String action : actions) { addTeleport(group.id, action); }
	}

	Entry addGroup(String name)
	{
		checkName(name);
		ensureCapacity();
		Entry entry = Entry.group(name.trim());
		entries.add(entry);
		return entry;
	}

	Entry addTeleport(String groupId, String destination)
	{
		checkDestination(destination);
		List<Entry> target = container(groupId);
		ensureCapacity();
		Entry entry = new Entry();
		entry.destination = CapeActionNames.canonical(destination);
		target.add(entry);
		return entry;
	}

	void rename(String id, String name)
	{
		checkName(name);
		Entry entry = find(id);
		if (!entry.isGroup())
		{
			throw new IllegalArgumentException("Only groups can be renamed.");
		}
		entry.name = name.trim();
	}

	void setColor(String id, Integer color)
	{
		checkColor(color);
		find(id).color = color;
	}

	void remove(String id)
	{
		List<Entry> parent = parent(id);
		parent.remove(find(id));
	}

	void move(String id, String groupId, int index)
	{
		Entry entry = find(id);
		List<Entry> target = container(groupId);
		if (entry.isGroup() && groupId != null)
		{
			throw new IllegalArgumentException("Groups cannot be nested.");
		}
		List<Entry> source = parent(id);
		source.remove(entry);
		target.add(Math.max(0, Math.min(index, target.size())), entry);
	}

	Entry find(String id)
	{
		return all().stream().filter(e -> e.id.equals(id)).findFirst()
			.orElseThrow(() -> new IllegalArgumentException("Entry no longer exists."));
	}

	List<Entry> parent(String id)
	{
		for (Entry entry : entries)
		{
			if (entry.id.equals(id))
			{
				return entries;
			}
			if (entry.children.stream().anyMatch(e -> e.id.equals(id)))
			{
				return entry.children;
			}
		}
		throw new IllegalArgumentException("Entry no longer exists.");
	}

	private List<Entry> container(String groupId)
	{
		if (groupId == null)
		{
			return entries;
		}
		Entry group = find(groupId);
		if (!group.isGroup())
		{
			throw new IllegalArgumentException("Choose a group.");
		}
		return group.children;
	}

	List<Entry> all()
	{
		List<Entry> result = new ArrayList<>();
		for (Entry entry : entries)
		{
			result.add(entry);
			result.addAll(entry.children);
		}
		return result;
	}

	private void ensureCapacity()
	{
		if (all().size() >= 100)
		{
			throw new IllegalArgumentException("A layout can contain up to 100 groups and shortcuts.");
		}
	}

	void validate()
	{
		if (version != 1 || entries == null || hiddenOriginals == null || !ORIGINALS.containsAll(hiddenOriginals)
			|| hiddenActions == null || hiddenActions.size() > 100)
		{
			throw new IllegalArgumentException("Unsupported or invalid layout configuration.");
		}
		for (String action : hiddenActions)
		{
			if (action == null || !plainText(action, 120) || !action.equals(CapeMenuTransformer.key(action))
				|| !(action.equals("spellbook") || action.equals("features")
					|| action.startsWith("spellbook/") || action.startsWith("features/")))
			{
				throw new IllegalArgumentException("Invalid hidden cape action.");
			}
		}
		Set<String> ids = new HashSet<>();
		for (Entry entry : entries)
		{
			validateEntry(entry, false, ids);
		}
		if (ids.size() > 100)
		{
			throw new IllegalArgumentException("Layout is too large.");
		}
	}

	private static void validateEntry(Entry entry, boolean child, Set<String> ids)
	{
		if (entry == null || entry.id == null || entry.id.isEmpty() || entry.id.length() > 64
			|| !ids.add(entry.id) || entry.children == null)
		{
			throw new IllegalArgumentException("Invalid layout entry.");
		}
		checkColor(entry.color);
		if (entry.isGroup())
		{
			if (child)
			{
				throw new IllegalArgumentException("Groups cannot be nested.");
			}
			checkName(entry.name);
			for (Entry nested : entry.children)
			{
				validateEntry(nested, true, ids);
			}
		}
		else
		{
			checkDestination(entry.destination);
			if (entry.name != null || !entry.children.isEmpty())
			{
				throw new IllegalArgumentException("A shortcut cannot contain other entries.");
			}
		}
	}

	static void checkName(String name)
	{
		if (!plainText(name, 40))
		{
			throw new IllegalArgumentException("Use a plain group name of 1–40 characters.");
		}
	}

	private static void checkColor(Integer color)
	{
		if (color != null && (color < 0 || color > 0xffffff))
		{
			throw new IllegalArgumentException("Invalid entry color.");
		}
	}

	private static void checkDestination(String name)
	{
		if (!plainText(name, 100))
		{
			throw new IllegalArgumentException("Invalid teleport name.");
		}
	}

	private static boolean plainText(String value, int limit)
	{
		return value != null && !value.trim().isEmpty() && value.length() <= limit
			&& value.indexOf('<') < 0 && value.indexOf('>') < 0
			&& value.chars().noneMatch(Character::isISOControl);
	}
}

package com.capemenuorganizer;

/** The two layouts are saved together; published instances are never edited in place. */
final class MenuLayouts
{
	final MenuLayout normal;
	final MenuLayout shift;

	MenuLayouts(MenuLayout normal, MenuLayout shift)
	{
		this.normal = normal;
		this.shift = shift;
	}

	MenuLayout forShift(boolean shiftPressed)
	{
		return shiftPressed ? shift : normal;
	}
}

